preludes.pgU16:
_PG_ASTRAL = __import__('re').compile('[\U00010000-\U0010FFFF]')
_PG_SURR = __import__('re').compile('[\ud800-\udfff]')
_PG_U16_CACHE = {}
_PG_U16_LAST = [None, None]
def _pg_u16_pair(m):
    c = ord(m.group(0)) - 0x10000
    return chr(0xD800 + (c >> 10)) + chr(0xDC00 + (c & 0x3FF))
def _pg_u16v(s):
    # the UTF-16 view of a non-ASCII str: each astral code point expanded to its surrogate pair. A short
    # string is just recomputed; a long one is cached (the last one, plus a small LRU), so indexing a long
    # string in a loop is O(1) per call even when short strings are indexed in between.
    last = _PG_U16_LAST
    if last[0] is s:
        return last[1]
    if len(s) < 256:
        return _PG_ASTRAL.sub(_pg_u16_pair, s)
    cache = _PG_U16_CACHE
    e = cache.pop(id(s), None)
    if e is not None and e[0] is s:
        v = e[1]
    else:
        v = _PG_ASTRAL.sub(_pg_u16_pair, s)
        if len(cache) >= 8:
            cache.pop(next(iter(cache)))
    cache[id(s)] = (s, v)
    last[0] = s
    last[1] = v
    return v
def _pg_len16(s):
    return len(s) if s.isascii() else len(_pg_u16v(s))
def _pg_u16_char(s, i):
    return s[i] if s.isascii() else _pg_u16v(s)[i]
def _pg_u16_cp(s, i):
    if s.isascii():
        return ord(s[i])
    v = _pg_u16v(s)
    c = ord(v[i])
    if 0xD800 <= c <= 0xDBFF and i + 1 < len(v):
        d = ord(v[i + 1])
        if 0xDC00 <= d <= 0xDFFF:
            return 0x10000 + ((c - 0xD800) << 10) + (d - 0xDC00)
    return c
def _pg_u16_sub(s, a, b):
    if s.isascii():
        return s[a:b]
    return _pg_u16_fix(_pg_u16v(s)[a:b])
def _pg_u16_find(s, n, f):
    if s.isascii():
        return s.find(n, f) if n.isascii() else -1
    return _pg_u16v(s).find(n if n.isascii() else _pg_u16v(n), f)
def _pg_cmp16(a, b):
    if not (a.isascii() and b.isascii()):
        a = a.encode('utf-16-be', 'surrogatepass')
        b = b.encode('utf-16-be', 'surrogatepass')
    return -1 if a < b else (1 if a > b else 0)
def _pg_u16_fix(r):
    # re-pair the surrogate halves of a UTF-16 view slice into the str's astral code points
    return r.encode('utf-16-le', 'surrogatepass').decode('utf-16-le', 'surrogatepass') if _PG_SURR.search(r) else r
def _pg_u16_lone(*xs):
    # a str holding a surrogate code point (a lone half a substring split off, or halves joined by +) only
    # matches like C#/TS in the UTF-16 view; without one, the code-point answer is the UTF-16 answer
    for x in xs:
        if not x.isascii() and _PG_SURR.search(x):
            return True
    return False
def _pg_u16_has(s, n):
    return _pg_u16v(s).find(_pg_u16v(n)) >= 0 if _pg_u16_lone(s, n) else n in s
def _pg_u16_starts(s, p):
    return _pg_u16v(s).startswith(_pg_u16v(p)) if _pg_u16_lone(s, p) else s.startswith(p)
def _pg_u16_ends(s, p):
    return _pg_u16v(s).endswith(_pg_u16v(p)) if _pg_u16_lone(s, p) else s.endswith(p)
def _pg_u16_replace(s, n, r):
    if _pg_u16_lone(s, n, r):
        return _pg_u16_fix(_pg_u16v(s).replace(_pg_u16v(n), _pg_u16v(r)))
    return s.replace(n, r)
def _pg_u16_split(s, sep):
    if _pg_u16_lone(s, sep):
        return [_pg_u16_fix(p) for p in _pg_u16v(s).split(_pg_u16v(sep))]
    return s.split(sep)

preludes.pgOut16:
def _pg_out16(s):
    # stdout: re-pair adjacent surrogate halves, and print a lone one as U+FFFD (as C# and Node do)
    return s if s.isascii() else s.encode('utf-16-le', 'surrogatepass').decode('utf-16-le', 'replace')

preludes.fdiv:
def _pg_fdiv(a, b):
    # IEEE division like C#/JS: x/0.0 is an infinity, 0.0/0.0 NaN (Python raises ZeroDivisionError)
    try:
        return a / b
    except ZeroDivisionError:
        if a != a or a == 0:
            return float("nan")
        return float("inf") if (a > 0) == (__import__('math').copysign(1.0, b) > 0) else float("-inf")
def _pg_fmod(a, b):
    # C# % on doubles: NaN for a zero divisor or an infinite dividend (math.fmod raises ValueError there)
    if b == 0 or a != a or b != b or a in (float("inf"), float("-inf")):
        return float("nan")
    return __import__('math').fmod(a, b)

preludes.pgInt:
def _pg_int(s):
    # the validated integer text, without the leading zeros that trip Python's 4300-digit int() limit
    d = s.lstrip("+-").lstrip("0") or "0"
    return -int(d) if s[:1] == "-" else int(d)

preludes.idiv:
def _pg_idiv(a, b):
    q = a // b
    return q + 1 if (q < 0 and q * b != a) else q
def _pg_irem(a, b):
    return a - _pg_idiv(a, b) * b

preludes.fstr:
def _pg_str(x):
    if x is None:
        return "null"
    if isinstance(x, bool):
        return "true" if x else "false"
    if not isinstance(x, float):
        return str(x)
    if x != x:
        return "NaN"
    if x in (float("inf"), float("-inf")):
        return "Infinity" if x > 0 else "-Infinity"
    if x == 0:
        return "0"
    s = repr(x)
    neg = s[0] == "-"
    if neg:
        s = s[1:]
    m, _, e = s.partition("e")
    i, _, f = m.partition(".")
    d = (i + f).lstrip("0")
    n = len(i) + (int(e) if e else 0) - (len(i) + len(f) - len(d))
    d = d.rstrip("0")
    k = len(d)
    if k <= n <= 21:
        r = d + "0" * (n - k)
    elif 0 < n <= 21:
        r = d[:n] + "." + d[n:]
    elif -6 < n <= 0:
        r = "0." + "0" * -n + d
    else:
        r = d[0] + ("." + d[1:] if k > 1 else "") + "e" + ("+" if n >= 1 else "-") + str(abs(n - 1))
    return "-" + r if neg else r
